<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import { brewApi } from '../api';
const props=defineProps({supplier:{type:Boolean,default:false}});
const schema=ref({types:[],categories:[],suppliers:[],beers:[],parents:[]}),items=ref([]),total=ref(0),page=ref(1),keyword=ref(''),includeInactive=ref(false),loading=ref(false),saving=ref(false),error=ref(''),formError=ref(''),editor=ref(false),review=ref(null),canManage=ref(false);
const draft=reactive({}),reviewNote=ref(''),parentId=ref('');
const stateNames={draft:'草稿',submitted:'待确认',confirmed:'已确认',returned:'需修改'};
const labels={capacity:'容量',material:'材质',closure:'口径 / 接口规格',position:'标签位置',dimensions:'尺寸',pack_count:'每箱装载数量',color:'颜色',supplier_code:'供应商货号',procurement_unit:'采购单位',unit_quantity:'每采购单位含多少库存单位',quote_price:'报价 / 采购单位',min_order:'起订量（采购单位）',lead_days:'交货周期（天）',artwork_version:'图稿版本',notes:'规格说明'};
const type=computed(()=>schema.value.types.find(t=>t.code===draft.type));
const fields=computed(()=>[...(type.value?.required||[]),'color']);
const canWrite=computed(()=>props.supplier||canManage.value);
async function load(){loading.value=true;error.value='';try{const data=await brewApi.listPackaging({page:page.value,page_size:30,keyword:keyword.value,include_inactive:includeInactive.value});items.value=data.items;total.value=data.total;canManage.value=data.can_manage;}catch(e){error.value=e.message;}finally{loading.value=false;}}
function open(item=null){formError.value='';Object.keys(draft).forEach(k=>delete draft[k]);Object.assign(draft,item?JSON.parse(JSON.stringify({...item,supplier_id:item.supplier?.id||'',image:undefined,existingImage:item.image})):{name:'',code:'',category_code:'',type:'',supplier_id:'',details:{unit:'个',capacity_unit:'mL',procurement_unit:'个',unit_quantity:1,quote_price:'',custom:false}});editor.value=true;}
function categoryChanged(){draft.type=schema.value.categories.find(c=>c.code===draft.category_code)?.type||'';const unit=draft.type==='label'?'张':'个';draft.details={unit,capacity_unit:'mL',procurement_unit:unit,unit_quantity:1,quote_price:'',custom:false};}
async function save(){saving.value=true;formError.value='';try{const data={name:draft.name,code:draft.code,category_code:draft.category_code,type:draft.type,details:draft.details,supplier_id:draft.supplier_id,version:draft.version};if(draft.image!==undefined)data.image=draft.image;await brewApi.savePackaging(draft.id,data);editor.value=false;await load();}catch(e){formError.value=e.message;}finally{saving.value=false;}}
async function action(item,name){saving.value=true;error.value='';try{await brewApi.packagingAction(item.id,name,{version:item.version,note:reviewNote.value,parent_id:parentId.value||null});review.value=null;await load();}catch(e){if(review.value)formError.value=e.message;else error.value=e.message;}finally{saving.value=false;}}
function startReview(item){review.value=item;reviewNote.value='';parentId.value='';formError.value='';}
function readFile(event,kind){const f=event.target.files[0];if(!f)return;if(f.size>3*1024*1024){formError.value='附件请控制在 3 MB 以内。';return;}const reader=new FileReader();reader.onload=()=>{const base=String(reader.result).split(',')[1];if(kind==='image')draft.image=base;else{draft.details.artwork_data=base;draft.details.artwork_name=f.name;}};reader.readAsDataURL(f);}
function specification(item){return schema.value.types.find(t=>t.code===item.type)?.required.map(k=>`${item.details[k]||'—'}${k==='capacity'?' '+item.details.capacity_unit:''}`).join(' · ')||'待补充规格';}
onMounted(async()=>{try{schema.value=await brewApi.packagingSchema();await load();}catch(e){error.value=e.message;}});
</script>
<template>
<section class="packaging-page">
<header class="packaging-toolbar"><div><h3>{{ supplier?'我的包装商品':'包装材料' }}</h3><p>分类来自原料种类中的包装材料；供应商商品经酒厂确认后可采购。</p></div><label class="pack-show-inactive"><input v-model="includeInactive" type="checkbox" @change="page=1;load()">包含停用</label><input v-model.trim="keyword" placeholder="搜索包装材料" @keyup.enter="page=1;load()"><button class="btn btn-sm btn-outline" @click="page=1;load()">搜索</button><button v-if="canWrite" class="btn btn-sm btn-primary" @click="open()">新增包装材料</button></header>
<div v-if="error" class="master-error">{{ error }}</div><div v-if="loading" class="empty">正在加载…</div>
<div v-else class="work-table-wrap"><table class="work-table"><thead><tr><th>材料 / 规格</th><th>类型</th><th>供应商</th><th>采购及报价</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><strong>{{ item.name }}</strong><small>{{ specification(item) }}</small><small v-if="item.details.custom">{{ schema.beers.find(b=>b.id===String(item.details.beer_product_id))?.name }} · {{ item.details.artwork_version }}</small></td><td>{{ schema.categories.find(c=>c.code===item.category_code)?.name||'包装材料' }}</td><td>{{ item.supplier?.name||'酒厂通用材料' }}</td><td>¥{{ item.details.quote_price??'—' }} / {{ item.details.procurement_unit||'—' }}<small>1 {{ item.details.procurement_unit }} = {{ item.details.unit_quantity }} {{ item.details.unit||item.unit }}</small></td><td><span :class="['pack-state',item.state]">{{ item.active ? stateNames[item.state] : '已停用' }}</span><small v-if="item.review_note">{{ item.review_note }}</small><small v-if="item.parent">关联 {{ item.parent.name }}</small></td><td class="pack-actions"><button v-if="canWrite" class="btn btn-xs btn-outline" @click="open(item)">详情 / 编辑</button><button v-if="supplier&&['draft','returned'].includes(item.state)" class="btn btn-xs btn-primary" :disabled="saving" @click="action(item,'submit')">提交确认</button><button v-if="!supplier&&canManage&&item.state==='submitted'" class="btn btn-xs btn-primary" @click="startReview(item)">确认商品</button><button v-if="canWrite" class="btn btn-xs btn-outline" :disabled="saving" @click="action(item,item.active?'archive':'restore')">{{ item.active?'停用':'启用' }}</button></td></tr></tbody></table><div v-if="!items.length" class="empty">暂无包装材料，先在原料种类中维护包装小类。</div></div>
<footer class="pack-pagination"><span>共 {{ total }} 件</span><button class="btn btn-xs btn-outline" :disabled="page<=1||loading" @click="page--;load()">上一页</button><span>{{ page }}</span><button class="btn btn-xs btn-outline" :disabled="page*30>=total||loading" @click="page++;load()">下一页</button></footer>
<Teleport to="body"><div v-if="editor" class="equipment-modal-mask" @click.self="!saving&&(editor=false)"><section class="equipment-modal pack-editor" role="dialog" aria-modal="true" aria-label="录入包装材料"><header class="equipment-modal-header"><div class="modal-title">{{ draft.id?'包装材料详情 / 编辑':'新增包装材料' }}</div><button class="equipment-close" :disabled="saving" @click="editor=false">×</button></header><form @submit.prevent="save"><div class="pack-form"><label>材料名称<input v-model.trim="draft.name" required></label><label>材料编码<input v-model.trim="draft.code" placeholder="选填"></label><label>包装小类<select v-model="draft.category_code" required @change="categoryChanged"><option value="">请选择</option><option v-for="c in schema.categories" :key="c.code" :value="c.code">{{ c.name }}</option></select></label><label v-if="!supplier">供应商<select v-model="draft.supplier_id"><option value="">酒厂通用材料，暂不关联</option><option v-for="s in schema.suppliers" :key="s.id" :value="s.id">{{ s.name }}</option></select></label>
<template v-if="draft.type"><label v-for="key in fields" :key="key">{{ labels[key] }}<div v-if="key==='capacity'" class="pack-capacity"><input v-model.number="draft.details.capacity" type="number" min="0.001" step="any" required><select v-model="draft.details.capacity_unit"><option>mL</option><option>L</option></select></div><select v-else-if="key==='position'" v-model="draft.details.position" required><option value="">请选择</option><option v-for="p in ['正标','背标','颈标','桶标','箱标']" :key="p">{{ p }}</option></select><input v-else v-model="draft.details[key]" :type="key==='pack_count'?'number':'text'" :min="key==='pack_count'?1:undefined" :required="type.required.includes(key)"></label>
<label>库存单位<select v-model="draft.details.unit"><option v-for="u in ['film','strap'].includes(draft.type)?['kg','m']:draft.type==='label'?['张']:['个']" :key="u">{{ u }}</option></select></label><label>采购单位<input v-model.trim="draft.details.procurement_unit" required placeholder="例如：箱、卷、个"></label><label>1 {{ draft.details.procurement_unit||'采购单位' }} 含多少 {{ draft.details.unit }}<input v-model.number="draft.details.unit_quantity" type="number" min="0.001" step="any" required></label><label>报价（元 / {{ draft.details.procurement_unit }}）<input v-model.number="draft.details.quote_price" type="number" min="0" step="0.01" required></label><label>供应商货号<input v-model.trim="draft.details.supplier_code"></label><label>起订量（{{ draft.details.procurement_unit }}）<input v-model.number="draft.details.min_order" type="number" min="0" step="any"></label><label>交货周期（天）<input v-model.number="draft.details.lead_days" type="number" min="0" step="1"></label><label class="pack-wide pack-check"><input v-model="draft.details.custom" type="checkbox">定制印刷包装</label><template v-if="draft.details.custom"><label>适用啤酒<select v-model="draft.details.beer_product_id" required><option value="">请选择</option><option v-for="beer in schema.beers" :key="beer.id" :value="beer.id">{{ beer.name }}</option></select></label><label>图稿版本<input v-model.trim="draft.details.artwork_version" required placeholder="例如：V2"></label><label>图稿附件<input type="file" accept=".pdf,.png,.jpg,.jpeg" @change="readFile($event,'artwork')"><a v-if="draft.details.artwork_data" :href="'data:application/octet-stream;base64,'+draft.details.artwork_data" :download="draft.details.artwork_name">{{ draft.details.artwork_name }}</a></label></template><label>商品图片<input type="file" accept="image/png,image/jpeg,image/webp" @change="readFile($event,'image')"><img v-if="draft.image||draft.existingImage" :src="'data:image/png;base64,'+(draft.image||draft.existingImage)" class="pack-preview"></label><label class="pack-wide">规格说明<textarea v-model.trim="draft.details.notes" rows="2"></textarea></label></template><div v-if="formError" class="master-error pack-wide">{{ formError }}</div></div><footer class="equipment-modal-footer"><button type="button" class="btn btn-secondary" :disabled="saving" @click="editor=false">取消</button><button class="btn btn-primary" :disabled="saving||!draft.type">{{ saving?'保存中…':supplier?'保存草稿':'保存材料' }}</button></footer></form></section></div>
<div v-if="review" class="equipment-modal-mask" @click.self="!saving&&(review=null)"><section class="equipment-modal pack-review" role="dialog" aria-modal="true" aria-label="确认包装商品"><header class="equipment-modal-header"><div class="modal-title">确认 {{ review.name }}</div><button class="equipment-close" @click="review=null">×</button></header><div class="pack-form"><p class="pack-wide">{{ specification(review) }}</p><label class="pack-wide">关联酒厂通用材料（选填）<select v-model="parentId"><option value="">作为独立包装商品确认</option><option v-for="p in schema.parents.filter(p=>p.type===review.type)" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><label class="pack-wide">确认意见 / 退回原因<textarea v-model.trim="reviewNote" rows="3"></textarea></label><div v-if="formError" class="master-error pack-wide">{{ formError }}</div></div><footer class="equipment-modal-footer"><button class="btn btn-outline" :disabled="saving" @click="action(review,'return')">退回修改</button><button class="btn btn-primary" :disabled="saving" @click="action(review,'confirm')">确认可采购</button></footer></section></div></Teleport>
</section>
</template>
<style scoped>
.packaging-toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:16px 0 24px}.packaging-toolbar>div{margin-right:auto}.packaging-toolbar h3{margin:0 0 8px}.packaging-toolbar p{color:#999;font-size:13px;margin:0}.work-table td small{display:block;color:#999;font-size:12px;margin-top:6px}.pack-actions{display:flex;gap:6px;flex-wrap:wrap}.pack-state{color:#aaa}.pack-state.confirmed{color:#9dc191}.pack-state.submitted{color:#d4a747}.pack-state.returned{color:#e69880}.pack-pagination{display:flex;align-items:center;justify-content:flex-end;gap:12px;margin-top:16px;color:#999;font-size:13px}.pack-editor{width:min(850px,95vw);max-height:90vh;overflow:auto}.pack-form{display:grid;grid-template-columns:1fr 1fr;gap:18px;padding:24px}.pack-form label{display:flex;flex-direction:column;gap:8px;font-size:13px}.pack-wide{grid-column:1/-1}.pack-form .pack-check{flex-direction:row;align-items:center}.pack-capacity{display:flex;gap:8px}.pack-capacity input{min-width:0;flex:1}.pack-capacity select{width:90px}.pack-preview{width:80px;height:80px;object-fit:contain}.pack-review{width:min(560px,95vw)}@media(max-width:600px){.pack-form{grid-template-columns:1fr;padding:16px}}
.pack-show-inactive{display:flex;align-items:center;gap:6px;font-size:12px;color:#aaa}
</style>
